package com.vaultora.vault;
import java.time.Instant;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;
@Service public class VaultService {private final VaultRepository vaults;public VaultService(VaultRepository vaults){this.vaults=vaults;}public VaultDtos.EncryptedVaultResponse get(String userId){return vaults.findByUserId(userId).map(VaultDtos.EncryptedVaultResponse::from).orElse(null);}public VaultDtos.EncryptedVaultResponse save(String userId,VaultDtos.EncryptedVaultRequest r,long expectedRevision){Vault v=vaults.findByUserId(userId).orElse(null);if(v==null){if(expectedRevision!=0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Vault revision conflict");v=new Vault();v.setUserId(userId);v.setCreatedAt(Instant.now());}else if(v.getRevision()!=expectedRevision)throw new ResponseStatusException(HttpStatus.CONFLICT,"Vault changed on another device. Unlock again before saving.");v.setCiphertext(r.ciphertext());v.setIv(r.iv());v.setSalt(r.salt());v.setVersion(r.version());v.setUpdatedAt(Instant.now());return VaultDtos.EncryptedVaultResponse.from(vaults.save(v));}}
